add_action( 'woocommerce_before_single_product', 'perfectpixel_fixed_qty_setup' );

function perfectpixel_fixed_qty_setup() {
	global $product;
	if ( ! $product || ! $product->is_type( 'simple' ) || ! $product->is_purchasable() || ! $product->is_in_stock() ) {
		return;
	}
	remove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_add_to_cart', 30 );
	add_action( 'woocommerce_single_product_summary', 'perfectpixel_fixed_qty_buttons', 30 );
}

function perfectpixel_fixed_qty_buttons() {
	global $product;
	$max = (int) $product->get_max_purchase_quantity(); // -1 = unlimited.
	echo '<div class="perfectpixel-fixed-qty" style="display:flex;flex-wrap:wrap;gap:.5em;margin-bottom:1.5em">';
	foreach ( wp_parse_id_list( '{{fixed_qty_values}}' ) as $qty ) {
		if ( $qty < 1 || ( $max > 0 && $qty > $max ) ) {
			continue;
		}
		printf(
			'<form method="post" action="%1$s" enctype="multipart/form-data"><input type="hidden" name="add-to-cart" value="%2$d"><input type="hidden" name="quantity" value="%3$d"><button type="submit" class="single_add_to_cart_button button alt">%4$s</button></form>',
			esc_url( $product->get_permalink() ),
			(int) $product->get_id(),
			(int) $qty,
			esc_html( str_replace( '{qty}', $qty, '{{fixed_qty_label}}' ) )
		);
	}
	echo '</div>';
}
